{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret formulerer indholdskravene som 'nyttigt' og 'bør' og ikke som krav i § 37 og vejledningens afsnit 4.2. Det nævner ikke, at dokumentationen skal være aktuel, at den skal vise en varig funktionsnedsættelse, og heller ikke at oplysningerne skal fremsendes, når de er tilgængelige i journalen. Udredningsforløbet og planlagt behandling mangler, og det fremhæves ikke, at erhvervsevnen kun beskrives hvis muligt. Diagnosen står som første punkt uden forbeholdet 'hvis stillet'. Svaret er ikke direkte forkert på alle punkter, men de svagt formulerede krav udgør en væsentlig juridisk unøjagtighed."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Flere kritiske elementer mangler: kravet om aktuel dokumentation, 'varig' funktionsnedsættelse og dens art og grad, udredningsforløbet, planlagt behandling og pligten til at fremsende de oplysninger, der er tilgængelige i journalen. Diagnose, sygdoms- og behandlingsforløb, funktionsniveau, igangværende behandling og erhvervsevne er dækket i substansen."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive, og indeholder ikke irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen identificerbar kilde som lovbestemmelse, bekendtgørelsesparagraf eller vejledningsafsnit. Det henviser kun generelt til 'SU's aktuelle vejledning'."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen identificerbar kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilden understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer indhold, der ikke har støtte i materialet. Det gælder 'mødestabilitet, arbejdstid og krav om tempo eller fleksibilitet', 'bivirkninger' og 'prognose/forventet varighed' som dokumentationsindhold, at flere helbredsproblemer 'så vidt muligt' bør beskrives samlet, og at 'lægen behøver ikke konkludere' ret til tillægget. Det fremstilles også som hovedkravet, at dokumentationen først og fremmest skal beskrive muligheden for lønnet arbejde. Vejledningen angiver erhvervsevne kun 'hvis muligt'. Påstanden 'En diagnose alene er normalt ikke nok' er i overensstemmelse med rubrikken, men svaret tilføjer også uunderstøttede elementer."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "De påkrævede forbehold mangler: 'hvis diagnose er stillet', 'hvis behandling er planlagt', 'hvis erhvervsevnen kan beskrives' og tilgængelighed i eksisterende lægefaglig dokumentation. Erhvervsevnen gøres tværtimod til det primære element uden 'hvis muligt'. Aktualitetskravet er heller ikke bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende, og konklusionerne følger af det, der siges. Det er vejledende og uden selvmodsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør lovens og vejledningens pligtudsagn ('skal vedlægge', 'skal fremsendes') til blot 'bør' og 'det er nyttigt'. Det svækker dermed den bindende modalitet. Samtidig gøres erhvervsevnen, som kun skal beskrives hvis muligt, til det primære krav ('først og fremmest')."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "partial",
      "reason": "Diagnose nævnes som første punkt ('hvad du fejler'). Forbeholdet 'hvis der er stillet en' mangler, og diagnose er ikke udtrykkeligt betinget."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret beskriver 'diagnose og forløb' og tilstandens udvikling samt behandlingsforløb, hvilket i substansen svarer til sygdomsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret beskriver 'behandling og prognose: igangværende eller afprøvet behandling, effekt og bivirkninger'. Det dækker behandlingsforløbet."
    },
    "A45": {
      "label": "no",
      "reason": "Planlagt behandling nævnes ikke. Svaret omtaler kun igangværende eller afprøvet behandling og forventninger til varighed."
    },
    "A47": {
      "label": "partial",
      "reason": "Påvirkningen af muligheden for lønnet arbejde er beskrevet og endda fremhævet. Forbeholdet 'hvis muligt' mangler, og erhvervsevnen fremstilles som det vigtigste krav."
    }
  },
  "overall_notes": "Svaret er relevant og sammenhængende og fanger flere af vejledningens elementer: diagnose, forløb, funktionspåvirkning, behandling og erhvervsevne. Det udelader aktualitet, varighed, udredning, planlagt behandling og kravet om at fremsende tilgængelige journaloplysninger. Det mister forbeholdene 'hvis stillet/planlagt/muligt'. Det svækker bindende krav til 'bør' og 'nyttigt' og tilføjer uunderstøttede detaljer. Der er ingen identificerbar kilde, så C04 er not_met og C05 og C06 er not_assessable."
}

